import csv
import io
import re


def parse_csv(raw_csv: str):
    text = raw_csv.lstrip("\ufeff")
    reader = csv.reader(
        io.StringIO(text, newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
        strict=False,
    )

    parsed = []
    while True:
        try:
            parsed.append(next(reader))
        except StopIteration:
            break
        except csv.Error:
            continue

    nonempty = [
        (index, row)
        for index, row in enumerate(parsed)
        if any(value.strip() for value in row)
    ]
    if not nonempty:
        return {"columns": [], "rows": []}

    header_patterns = (
        r"\bname\b",
        r"\btitle\b",
        r"\bgrade\b",
        r"\bdepartment\b",
        r"\borganisation\b",
        r"\borganization\b",
        r"\breference\b",
        r"\bphone\b",
        r"\be-?mail\b",
        r"\bsalary\b",
        r"\bfte\b",
        r"\bvalid\b",
        r"\bnotes?\b",
        r"\bfunction\b",
        r"\bcontact\b",
        r"\breports?\b",
        r"\bpay\b",
        r"\bgroup\b",
    )

    def header_score(row):
        values = [value.strip().lower() for value in row]
        joined = " ".join(values)
        score = sum(
            1
            for pattern in header_patterns
            if re.search(pattern, joined, flags=re.IGNORECASE)
        )
        if len(row) == 19:
            score += 3
        if any("reference" in value for value in values):
            score += 3
        if sum(bool(value) for value in values) >= 5:
            score += 1
        return score

    candidates = [(header_score(row), index, row) for index, row in nonempty]
    strong = [item for item in candidates if item[0] >= 4]
    if strong:
        _, header_index, header = max(strong, key=lambda item: (item[0], -item[1]))
    else:
        suitable = [
            item for item in candidates
            if len(item[2]) >= 2
        ]
        if suitable:
            _, header_index, header = suitable[0]
        else:
            header_index, header = nonempty[0]

    data_rows = parsed[header_index + 1:]
    width = max(19, len(header), max((len(row) for row in data_rows), default=0))
    columns = list(header)
    while len(columns) < width:
        position = len(columns) + 1
        columns.append(f"Column {position}")

    rows = []
    for row in data_rows:
        if not row or not any(value.strip() for value in row):
            continue
        normalized = list(row[:width])
        normalized.extend([""] * (width - len(normalized)))
        rows.append(normalized)

    return {"columns": columns, "rows": rows}
